/* ---------- the registry ---------- */
let _ct={s:null,m:new Map()};
function customTools(hub){const s=get.settings();if(_ct.s!==s){_ct={s,m:new Map()};(s.customMods||[]).forEach(m=>{const l=_ct.m.get(m.hub)||[];l.push(tplTool(Object.assign({},m,{custom:true,optIn:false})));_ct.m.set(m.hub,l);});}return _ct.m.get(hub)||[];}
function toolsOf(hub){return[...((HUBS[hub]||{}).tools||[]),...customTools(hub)];}
function setToolOn(hub,id,on){const s=get.settings(),t=toolOf(hub,id);if(!t)return;const hid=Object.assign({},s.hubHidden||{}),sh=Object.assign({},s.hubShown||{});const off=(hid[hub]||[]).filter(x=>x!==id),yes=(sh[hub]||[]).filter(x=>x!==id);if(!on)off.push(id);else if(t.optIn)yes.push(id);hid[hub]=off;sh[hub]=yes;setSettings({hubHidden:hid,hubShown:sh});}
const toolOn=(hub,id)=>!hubHidden(hub).includes(id);
function turnOnTool(hub,t,{go=false}={}){setToolOn(hub,t.id,true);const s=get.settings();if(!(s.areas||AREAS).includes(hub))setSettings({areas:[...(s.areas||AREAS),hub]});toast(`${t.name} is on`,()=>setToolOn(hub,t.id,false));if(go)App.go('tool',{hub,tool:t.id});else App.refresh();}
const modAreas=()=>{const s=get.settings(),mine=s.areas||AREAS,extra=[...new Set([...Object.keys(HUBS),...(s.customMods||[]).map(m=>m.hub)])].filter(a=>!mine.includes(a));return{mine,extra};};

/* ---------- the shared contract: where each module shows up ---------- */
const FEEDS=['Today','Calendar','Search','Review'];
function feedsOf(hub,t){const f=new Set(['Search','Review']),ti=TOOL_INTRO[t.id]||t.intro;(ti&&ti.shows||[]).forEach(([w])=>{const n=TI_W[w][1];if(n==='Weekly review')f.add('Review');else if(n==='Today'||n==='Calendar')f.add(n);});if(t.tpl==='checklist'||t.dueKey)f.add('Today');if(t.dueKey&&t.after)f.add('Calendar');if(isPinned(hub,t.id))f.add('Today');return FEEDS.filter(x=>f.has(x));}
